const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={store:'S01',date:preferences.startDate,filter:'all',search:'',nav:'overview',selected:null,plan:'balanced',overrides:{}};
let DATA,TEAM,PROMO,ENGINE_PARAMS,currentPromotionForecast,currentMenuForecast,engineCtx,ENGINE,DRAFT,items=[],focusBefore;
const forecastWindow=()=>TEAM?.windows[state.date];
const hasForecast=()=>!!forecastWindow()?.stores[state.store];
const n=(v,d=0)=>Number(v).toLocaleString('ko-KR',{maximumFractionDigits:d});
const money=v=>'₩'+n(v);
function day(ds,offset=0){let d=new Date(ds+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+offset);return d.toISOString().slice(0,10)}
const weekday=ds=>['일','월','화','수','목','금','토'][new Date(ds+'T00:00:00Z').getUTCDay()];
const days=(a,b)=>Math.round((new Date(b+'T00:00:00Z')-new Date(a+'T00:00:00Z'))/86400000);
const md=ds=>`${+ds.slice(5,7)}.${+ds.slice(8,10)}`;
function qty(v,i){return i.use_unit==='g'?n(v/1000,3)+' kg':i.use_unit==='ml'?n(v/1000,3)+' L':n(v,1)+' '+i.use_unit}
function simulate(i,packs=0,horizon=7){return FreshOrderEngine.simulate(i,packs,horizon)}
/* 팀 발주 엔진(engine-core.js): 성향별 발주안 생성 → 같은 시나리오로 위험 평가. 화면의 재고 상태(부족·폐기·과잉)는 기존 7일 계산기 기준 */
function calculate(){
 currentPromotionForecast=policyProjection().ingredients;
 const result=calculatePolicy();engineCtx=result.ctx;ENGINE=result.engine;
 const chosen=result.candidates.find(c=>c.name===policySelection)||result.best;
 items=result.items.map(raw=>{const i={...raw};i.engine=(chosen?.recommend||result.engine.presets.current.recommend)[i.ingredient_id];i.baseRecommended=i.engine.order_qty;i.recommended=chosen?.quantities[i.ingredient_id]||0;i.orderQty=state.overrides[i.ingredient_id]??i.recommended;return i;});
 evaluateDraft(false);renderOrderPlans();renderPromotions();
}
function evaluateDraft(rerender=true){DRAFT=OrderEngine.evaluate(items,Object.fromEntries(items.map(i=>[i.ingredient_id,i.orderQty])),engineCtx);if(rerender){renderPlanCompare();renderPolicyHome();}}
const selectedCandidate=()=>policyResult?.candidates.find(c=>c.name===policySelection)||policyResult?.best;
const selectedPlan=()=>({name:selectedCandidate()?.name||'조건 미충족'});
const planInfo=id=>({service_level:selectedCandidate()?.service_level||effectivePolicy().preferences.service_level,chosen:selectedCandidate()||{variant:'조건 미충족'}});
const pct=v=>Math.round(v*100)+'%';
const variantLabel=c=>c.variant==='기본'?'':` · ${c.variant}`;
function renderOrderPlans(){renderPolicyPlans();}
function renderPlanCompare(){}
const labels={all:'전체',short:'부족 예상',waste:'폐기 위험',excess:'과잉',ok:'적정'};
const badges=i=>`${i.short>.01?'<span class="badge short">부족 예상</span>':''}${i.waste>.01?'<span class="badge waste">폐기 위험</span>':''}${i.short<=.01&&i.waste<=.01?`<span class="badge ${i.excess?'excess':''}">${i.excess?'과잉':'적정'}</span>`:''}`;
const icons=i=>i.storage==='냉동'?'❄':i.storage==='상온'?'▱':'♧';
function count(k){return items.filter(i=>k==='all'||k==='waste'&&i.waste>.01||k==='short'&&i.short>.01||k==='excess'&&i.excess||k==='ok'&&i.status==='ok').length}
function render(){activeSnapshot=resolveSnapshot();if(!activeSnapshot||!hasForecast()){items=[];$('#storeTabs').innerHTML=DATA.stores.map(s=>`<button class="store-tab ${s.store_id===state.store?'active':''}" data-store="${s.store_id}">매장 ${s.store_id==='S01'?'A':s.store_id==='S02'?'B':'C'}<small>${s.trade_area}</small></button>`).join('');applyNav();return}calculate();$('#storeTabs').innerHTML=DATA.stores.map(s=>`<button class="store-tab ${s.store_id===state.store?'active':''}" data-store="${s.store_id}">매장 ${s.store_id.slice(-1)==='1'?'A':s.store_id.slice(-1)==='2'?'B':'C'}<small>${s.trade_area}</small></button>`).join('');$('#snapshotText').textContent=`${state.date.replaceAll('-','.')} 마감 재고 기준 · 다음 날부터 7일 예측`;
const total=items.reduce((a,i)=>a+i.orderQty*i.price,0), orderCount=items.filter(i=>i.orderQty>0).length;
$('#metrics').innerHTML=[['부족 예상',n(count('short')),'개','추가 발주 없이 7일 유지 시','↘'],['폐기 위험',n(count('waste')),'개','사용기한 내 미소진 예상','◷'],['과잉 재고',n(count('excess')),'개','현재 재고 > 7일 예상 소요량','▥'],['발주 금액',n(total),'원',`${orderCount}개 품목 · 공급사 조건 확인 필요`,'↗']].map(([title,v,unit,foot,icon])=>`<article class="metric"><div class="metric-top">${title}<span class="metric-icon">${icon}</span></div><div class="metric-value">${v}<small>${unit}</small></div><div class="metric-foot">${foot}</div></article>`).join('');
const wasteValue=items.reduce((a,i)=>a+i.waste*i.price/i.use_qty_per_order_unit,0);$('#insight').innerHTML=count('waste')?`<span class="insight-icon">✧</span><span><b>${count('waste')}개 품목 사용기한 임박</b> 7일 내 미소진 예상 ${money(wasteValue)}입니다.</span><button id="showWaste">폐기 위험 보기 →</button>`:`<span class="insight-icon">✧</span><span><b>현재 수요 전망에서 사용기한 경과에 따른 폐기는 예상되지 않습니다.</b> 추가 발주 없이 유지할 경우의 부족 위험을 확인해주세요.</span><button id="showWaste">재고 현황 보기 →</button>`;
$('#insight').classList.toggle('no-waste',count('waste')===0);$('#showWaste').onclick=()=>{state.filter=count('waste')?'waste':'all';renderTable();$('#inventoryPanel').scrollIntoView({behavior:'smooth',block:'start'})};
$('#chartSelect').innerHTML=items.map(i=>`<option value="${i.ingredient_id}">${i.ingredient_name}</option>`).join('');if(!state.selected||!items.find(i=>i.ingredient_id===state.selected))state.selected=items.find(i=>i.waste>.01)?.ingredient_id||items[0].ingredient_id;$('#chartSelect').value=state.selected;renderChart();
const priorities=[...items].sort((a,b)=>(b.waste>0)-(a.waste>0)||b.waste*b.price/b.use_qty_per_order_unit-a.waste*a.price/a.use_qty_per_order_unit).filter(i=>i.short>.01||i.waste>.01).slice(0,3);
$('#priorities').innerHTML=priorities.length?priorities.map((i,index)=>`<button class="priority-item" data-item="${i.ingredient_id}"><span class="priority-num">0${index+1}</span><div class="priority-text"><b>${i.ingredient_name} <span class="badge ${i.waste>.01?'waste':'short'}">${i.waste>.01?'폐기 위험':'부족 예상'}</span></b><small>${i.waste>.01?`7일 내 ${qty(i.waste,i)} 미소진 예상`:`7일 내 ${qty(i.short,i)} 부족 예상`}</small></div><span>↗</span></button>`).join(''):'<p style="padding:30px 23px">예상되는 부족·폐기 위험이 없습니다.</p>';
$('#navCount').textContent=orderCount;renderTable();bindItems();applyNav();}
function renderTable(){
const filtered=items.filter(i=>(state.filter==='all'||state.filter==='waste'&&i.waste>.01||state.filter==='short'&&i.short>.01||state.filter==='excess'&&i.excess||state.filter==='ok'&&i.status==='ok')&&i.ingredient_name.includes(state.search));
$('#filters').innerHTML=Object.keys(labels).map(k=>`<button class="filter ${state.filter===k?'active':''}" data-filter="${k}">${labels[k]}<small>${count(k)}</small></button>`).join('');
$('#inventoryBody').innerHTML=filtered.map(i=>`<tr data-item="${i.ingredient_id}" tabindex="0" aria-label="${i.ingredient_name} 발주 근거 보기"><td><div class="item-name"><span class="ingredient-icon">${icons(i)}</span><div><b>${i.ingredient_name}</b><small>${i.ingredient_id} · ${i.storage}</small></div></div></td><td>${qty(i.stock,i)}</td><td>${qty(i.total,i)}</td><td>${badges(i)}</td><td class="draft-edit-cell"><div class="inline-qty"><input data-order-input="${i.ingredient_id}" type="number" min="0" max="10000" step="1" value="${i.orderQty}" aria-label="${i.ingredient_name} 발주 수량"><span>${i.order_unit}</span></div><small>${i.orderQty===i.recommended?'추천 수량':'수동 수정 · 추천 '+n(i.recommended)}</small></td><td class="order-qty" data-order-amount="${i.ingredient_id}">${money(i.orderQty*i.price)}</td><td><button class="row-arrow" aria-label="${i.ingredient_name} 발주 근거 보기">↗</button></td></tr>`).join('');
$('#itemCount').textContent=items.length;$('#empty').hidden=filtered.length>0;$('#tableCount').textContent=`${filtered.length} / ${items.length}개 품목 · 발주 전 기준`;
$$('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;renderTable()});bindItems();
$$('[data-order-input]').forEach(input=>{
input.onclick=e=>e.stopPropagation();input.onkeydown=e=>e.stopPropagation();
const valid=()=>input.value!==''&&Number.isInteger(Number(input.value))&&Number(input.value)>=0&&Number(input.value)<=10000&&(Number(input.value)===0||Number(input.value)>=items.find(i=>i.ingredient_id===input.dataset.orderInput).min_order_qty);
const commit=()=>{const i=items.find(x=>x.ingredient_id===input.dataset.orderInput),value=Number(input.value);state.overrides[i.ingredient_id]=value;i.orderQty=value;input.closest('td').querySelector('small').textContent=value===i.recommended?'추천 수량':'수동 수정 · 추천 '+n(i.recommended);$(`[data-order-amount="${i.ingredient_id}"]`).textContent=money(value*i.price);const count=items.filter(x=>x.orderQty>0).length,total=items.reduce((sum,x)=>sum+x.orderQty*x.price,0),card=$('#metrics .metric:last-child');card.querySelector('.metric-value').innerHTML=n(total)+'<small>원</small>';card.querySelector('.metric-foot').textContent=count+'개 품목 · 공급사 조건 확인 필요';$('#navCount').textContent=count;evaluateDraft();};
input.oninput=()=>{input.setAttribute('aria-invalid',valid()?'false':'true');if(valid())commit()};input.onchange=()=>{if(!valid()){input.value=items.find(i=>i.ingredient_id===input.dataset.orderInput).orderQty;input.setAttribute('aria-invalid','false');toast('0 또는 최소 발주량 이상의 정수를 입력해주세요.');return}commit()};
});
}
function bindItems(){$$('[data-item]').forEach(b=>{b.onclick=()=>openItem(b.dataset.item);b.onkeydown=e=>{if(e.key==='Enter')openItem(b.dataset.item)}})}
function renderChart(){const i=items.find(i=>i.ingredient_id===state.selected);if(!i)return;const past=i.history.slice(-7),future=i.trace, all=[...past,...future], max=Math.max(...all.map(p=>p.qty),i.avg,1)*1.15;const W=650,H=175,L=46,R=20,T=12,B=32,iw=W-L-R,ih=H-T-B, x=index=>L+index/(all.length-1)*iw,y=v=>T+ih-v/max*ih;const path=(rows,start)=>rows.map((p,j)=>`${j?'L':'M'}${x(start+j).toFixed(1)},${y(p.qty).toFixed(1)}`).join(' ');const hist=path(past,0),proj=path([past.at(-1),...future],past.length-1),boundary=x(past.length-1);let grid='';for(let j=0;j<4;j++){let val=max*j/3,yy=y(val);grid+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#edf1e9" stroke-dasharray="3 4"/><text x="${L-10}" y="${yy+3}" text-anchor="end" fill="#acb5ab" font-size="9">${n(i.use_unit==='g'||i.use_unit==='ml'?val/1000:val,1)}</text>`}const unit=i.use_unit==='g'?'kg':i.use_unit==='ml'?'L':i.use_unit;$('#chart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${i.ingredient_name} 과거 재고와 향후 7일 예상 재고, 단위 ${unit}"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#f4dd9c" stop-opacity=".6"/><stop offset="100%" stop-color="#fffaf0" stop-opacity=".1"/></linearGradient></defs><text x="${L}" y="6" font-size="8" fill="#a0aea1">${unit}</text><rect x="${boundary}" y="${T}" width="${W-R-boundary}" height="${ih}" fill="#fffbef" rx="3"/>${grid}<path d="${hist} L${boundary},${y(0)} L${L},${y(0)} Z" fill="url(#area)"/><path d="${hist}" fill="none" stroke="#292824" stroke-width="2.3" stroke-linecap="round"/><path d="${proj}" fill="none" stroke="#d7a019" stroke-width="2" stroke-dasharray="5 5" stroke-linecap="round"/><line x1="${boundary}" x2="${boundary}" y1="${T}" y2="${y(0)}" stroke="#dce5d7" stroke-dasharray="3 4"/><circle cx="${boundary}" cy="${y(past.at(-1).qty)}" r="4" fill="#292824" stroke="white" stroke-width="2"/>${all.filter((p,j)=>j%2===0).map(p=>`<text x="${x(all.indexOf(p))}" y="${H-10}" text-anchor="middle" fill="#a0aca0" font-size="9">${md(p.date)}</text>`).join('')}<text x="${boundary+8}" y="${T+10}" fill="#a2ae9c" font-size="8">예측 구간</text></svg>`;}
function showDrawer(html){focusBefore=document.activeElement;$('#drawer').innerHTML=html;$('#drawer').hidden=false;$('#drawerOverlay').hidden=false;document.body.style.overflow='hidden';$('#drawer').querySelector('.close-drawer').onclick=closeDrawer;$('#drawer').querySelector('.close-drawer').focus()}
function closeDrawer(){$('#drawer').hidden=true;$('#drawerOverlay').hidden=true;document.body.style.overflow='';focusBefore?.focus()}
function openItem(id){
state.selected=id;$('#chartSelect').value=id;renderChart();const i=items.find(x=>x.ingredient_id===id),sc=i.sc,s=sc.supplier,after=simulate(i,i.orderQty),e=i.engine,r=DRAFT.lines[i.ingredient_id];
showDrawer(`<div class="drawer-header"><div><div class="eyebrow">ITEM DETAIL</div><h2>${i.ingredient_name}</h2><p>${state.date} 마감 기준 · ${s.supplier_name}</p></div><button class="icon-button close-drawer" aria-label="닫기">×</button></div><h3>발주 전후 비교</h3><table><thead><tr><th>향후 7일 예상</th><th>신규 발주 전</th><th>현재 초안 반영</th></tr></thead><tbody><tr><td>부족량</td><td>${qty(i.short,i)}</td><td>${qty(after.short,i)}</td></tr><tr><td>기한 경과 미소진량</td><td>${qty(i.waste,i)}</td><td>${qty(after.waste,i)}</td></tr></tbody></table><div class="explanation">현재 초안 ${n(i.orderQty)} ${i.order_unit}를 ${sc.arrival}에 받는 경우의 초기 시뮬레이션입니다. 이후 추가 발주는 포함하지 않습니다.</div><h3>엔진 추천 계산 · ${selectedPlan().name} (서비스 ${pct(e.service_level)})</h3><div class="calc-line">발주 → 입고<b>${md(e.order_date)} ${s.order_cutoff} 마감 전 → ${md(e.arrival1)} 오전 7시</b></div><div class="calc-line">커버해야 하는 기간<b>${md(e.window_start)}–${md(e.window_end)} · ${e.window_days}일 (다음 입고 ${md(e.arrival2)} 전날까지)</b></div><div class="calc-line">예측 소요<b>${qty(e.demand_window,i)}</b></div>${e.unmet_before_arrival1>1e-9?`<div class="calc-line">− 입고 전 부족분 (이번 발주로 못 막음)<b>${qty(e.unmet_before_arrival1,i)}</b></div>`:''}<div class="calc-line">+ 안전재고 (z ${n(e.z,2)} × σ ${qty(e.sigma_window,i)})<b>${qty(e.safety_stock,i)}</b></div><div class="calc-line">+ 추가 수요 여유<b>${qty(e.extra_buffer||0,i)}</b></div><div class="calc-line">− 가용 재고${e.expiring_excluded>1e-9?` (기한 지날 ${qty(e.expiring_excluded,i)} 제외)`:''}<b>${qty(e.available,i)}</b></div><div class="calc-line">− 기존 미입고 발주량<b>${qty(e.inbound,i)}</b></div><div class="calc-line">= 필요량 ${qty(e.net_need_use,i)} → ${n(e.raw_units,2)} ${i.order_unit} → 올림·최소 ${n(e.min_order_qty)}<b>${n(e.order_qty)} ${i.order_unit}</b></div><div class="calc-line">선택안 최종 / 현재 초안<b>${n(i.recommended)} / ${n(i.orderQty)} ${i.order_unit}</b></div><div class="calc-line">현재 초안 금액<b>${money(i.orderQty*i.price)}</b></div><h3>현재 초안의 위험 · 시나리오 ${n(DRAFT.totals.n_scenarios)}개</h3><div class="calc-line">다음 입고 전 품절 확률<b>${pct(r.p_stockout_window)}</b></div><div class="calc-line">부족량 평균 / 90백분위<b>${qty(r.shortage_window_mean,i)} / ${qty(r.shortage_window_p90,i)}</b></div><div class="calc-line">7일 내 폐기 평균 / 90백분위<b>${qty(r.waste_mean,i)} / ${qty(r.waste_p90,i)}</b></div><div class="calc-line">이 품목이 막는 메뉴 매출 (평균)<b>${money(r.lost_revenue_mean)}</b></div><div class="explanation">σ: ${e.sigma_note}. 수요는 팀 프로모션 수정 모델의 비행사 기준 수요에 공휴일과 점장이 적용한 수요 반응, BOM을 반영한 값이며 할인율만으로 수요 증가율을 추정하지 않습니다. 선택안 최종 수량은 공급사 최소 발주금액 처리(연기·증량)까지 반영한 값입니다. 수량 수정은 분석 목록에서 한 번만 입력하면 됩니다.</div><button class="button secondary" id="backToPlan">발주 수량 목록으로 돌아가기</button>`);
$('#backToPlan').onclick=()=>{closeDrawer();$('#inventoryPanel').scrollIntoView({behavior:'smooth',block:'start'})};
}
function reviewOrders(){try{checkDraft()}catch(e){toast(e.message);return;}const orders=items.filter(i=>i.orderQty>0),total=orders.reduce((a,i)=>a+i.orderQty*i.price,0),warnings=DATA.suppliers.map(s=>{const sum=orders.filter(i=>i.supplier_id===s.supplier_id).reduce((a,i)=>a+i.orderQty*i.price,0);return sum>0&&sum<+s.min_order_amount?`<div class="warning">${s.supplier_name}: 최소 발주금액 ${money(+s.min_order_amount)}에 ${money(+s.min_order_amount-sum)} 부족합니다. 현재 초안은 정기발주 조건을 충족하지 못합니다.</div>`:''}).join('');showDrawer(`<div class="drawer-header"><div><div class="eyebrow">PURCHASE ORDER</div><h2>발주 발주서 확인</h2><p>${DATA.stores.find(s=>s.store_id===state.store).store_name} · ${state.date} 마감 기준</p></div><button class="icon-button close-drawer" aria-label="닫기">×</button></div><p><b>${selectedPlan().name} · 서비스 ${pct(planInfo(state.plan).service_level)}${variantLabel(planInfo(state.plan).chosen)}</b><br>발주 신청 목록에서 조정한 수량을 최종 확인하세요.</p>${orders.map(i=>`<div class="order-list"><div><b>${i.ingredient_name}</b><small>${n(i.orderQty)} ${i.order_unit} · ${md(i.sc.order)} 발주 → ${md(i.sc.arrival)} 입고</small></div><b>${money(i.orderQty*i.price)}</b></div>`).join('')||'<div class="empty">현재 초안에 포함된 발주 품목이 없습니다.</div>'}<div class="order-total"><span>예상 발주금액</span><strong>${money(total)}</strong></div><div class="explanation">이 초안의 위험 · 다음 입고 전 품절 확률 <b>${pct(DRAFT.totals.p_any_stockout)}</b> · 기대 손실 <b>${money(DRAFT.totals.mean_loss)}</b> (품절 ${money(DRAFT.totals.mean_lost_revenue)} + 폐기 ${money(DRAFT.totals.mean_waste_value)}) · 손실 90백분위 ${money(DRAFT.totals.p90_loss)}</div>${warnings}<div class="explanation">공급사별 발주일이 다를 수 있습니다. 이 초안은 외부 공급사에 전송되지 않으며, 다운로드 후 검토용으로 사용할 수 있습니다.</div><button class="button primary" id="exportDraft">발주서 다운로드</button><button class="button secondary" id="resetDraft">수정 수량을 선택안 추천값으로 초기화</button>`);$('#exportDraft').onclick=download;$('#resetDraft').onclick=()=>{state.overrides={};render();reviewOrders();toast('선택한 발주안의 수량으로 초기화했습니다.')};}
function download(){try{checkDraft()}catch(e){toast(e.message);return;}let lines=[['재고기준일','매장','식자재','사용단위','현재재고','7일예상소요','7일폐기예상','7일부족예상','발주수량','발주단위','발주금액','발주가능일','예정입고일','구분','수요모델','판매관측기준일','선택발주안','서비스수준','최소금액처리','안전재고','품목품절확률','추가행사조건']];for(const i of items.filter(i=>i.orderQty>0))lines.push([state.date,state.store,i.ingredient_name,i.use_unit,i.stock,i.total.toFixed(2),i.waste.toFixed(2),i.short.toFixed(2),i.orderQty,i.order_unit,i.orderQty*i.price,i.sc.order,i.sc.arrival,'추천 초안·실제 전송 아님',TEAM.model_id,forecastWindow().data_through,selectedPlan().name,planInfo(state.plan).service_level,planInfo(state.plan).chosen.variant,i.engine.safety_stock.toFixed(2),DRAFT.lines[i.ingredient_id].p_stockout_window.toFixed(3),JSON.stringify({promotions:getPromotionPlans(),policy:effectivePolicy(),order_request:orderRequest,evaluation:'team-order-engine',scope:'current-store'})]);const csv='\ufeff'+lines.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=`발주초안_${state.store}_${state.date}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('발주 초안을 다운로드했습니다.')}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function applyNav(){
renderPolicyHome();const history=state.nav==='history',daily=state.nav==='daily',missing=state.nav==='overview'&&(!activeSnapshot||!hasForecast());
$('#planningEmpty').hidden=!missing;$('#orderPlanSection').hidden=history||daily||missing;$('#promotionSection').hidden=history||daily||missing;
const forecastMissing=!!activeSnapshot&&!hasForecast();
$('#planningEmpty h2').textContent=forecastMissing?'예측 데이터 없음':'마감 재고 없음';
$('#planningEmpty p').textContent=forecastMissing?'현재 팀 예측은 2026년 10월 14일 기준일까지 준비되어 있습니다. 재고 기록은 계속할 수 있으며, 이후 발주 추천에는 최신 판매 데이터로 갱신한 예측이 필요합니다.':'선택한 날짜의 재고를 저장하면 필요한 발주 수량과 폐기 위험을 계산합니다.';
$('#navCount').textContent=items.filter(i=>i.orderQty>0).length;
$('#forecastNote').hidden=history||daily||missing;
if(hasForecast())$('#forecastNote').textContent=`팀 프로모션 수정 모델 · 추가 조건 ${getPromotionPlans().length}건 · 판매 관측 ${forecastWindow().data_through}까지 · ${md(forecastWindow().dates[0])}–${md(forecastWindow().dates.at(-1))} 소요량 · 발주 엔진: 안전재고 + 과거 오차 시나리오 ${ENGINE_PARAMS.scenarios.n}개`;$('#planningRecordBtn').onclick=()=>{state.nav='daily';applyNav()};
const title={daily:'일일 재고 기록',overview:'발주 신청',history:'과거 발주 이력'}[state.nav];
$('#breadcrumb').textContent=title;$('label[for="dateSelect"]').textContent=history?'조회 기준일':'재고 기준일';
$('#pageTitle').textContent=daily?`${+state.date.slice(5,7)}월 ${+state.date.slice(8,10)}일, 재고 마감 확인`:history?'발주 내역':'오늘의 발주';
$('#subtitle').textContent=daily?(state.date>DailyLedger.SEED?'':''):history?'':'';
$('#tableTitle').firstChild.textContent='추천 발주 목록 ';
$('#analysisRow').classList.toggle('overview-hidden',state.nav!=='overview'||missing);$('#insight').classList.toggle('overview-hidden',history||daily||missing);$('#metrics').classList.toggle('overview-hidden',history||daily||missing);$('#inventoryPanel').hidden=history||daily||missing;$('#purchaseHistory').hidden=!history;$('#dailyInventory').hidden=!daily;$('#reviewBtn').hidden=history||daily||missing;$('#reviewBtn').disabled=requestDirty||!policyResult?.best;
$('#assumptionsBtn').textContent=history||daily?'데이터 기준 보기 ↗':'예측 기준 보기 ↗';
$('#snapshotText').textContent=daily?`${state.date.replaceAll('-','.')} ${state.date>DailyLedger.SEED?(activeSnapshot?'점장 입력 마감 기록':'일일 재고 입력'):'마감 실제 기록'} · 입고 예정과 현재 재고 분리`:history?`${state.date.replaceAll('-','.')} 마감까지의 발주·입고 기록 · 실시간 연동 아님`:`${state.date.replaceAll('-','.')} 마감 재고 기준 · 다음 날부터 7일 예측`;
$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===state.nav));if(history)renderPurchaseHistory();if(daily){if(activeSnapshot){renderDailyInventory();if(state.date>DailyLedger.SEED)attachSavedActions();else{const starter=document.createElement('div');starter.className='entry-saved-actions';starter.innerHTML='<button class="button primary" id="startOctober">10월 1일 기록 시작 →</button>';$('#dailyInventory').append(starter);$('#startOctober').onclick=()=>selectRecordDate('2026-10-01');}}else renderDailyEntry();}
}
async function init(){try{const res=await fetch('data.json');if(!res.ok)throw Error(res.status);DATA=await res.json();const teamResponse=await fetch('team-forecasts.json');if(!teamResponse.ok)throw Error('팀 예측을 불러오지 못했습니다.');TEAM=await teamResponse.json();const promoResponse=await fetch('promotion-inputs.json');if(!promoResponse.ok)throw Error('행사 예측 입력을 불러오지 못했습니다.');PROMO=await promoResponse.json();const engineResponse=await fetch('engine-params.json');if(!engineResponse.ok)throw Error('발주 엔진 파라미터를 불러오지 못했습니다.');ENGINE_PARAMS=await engineResponse.json();OrderEngine.configure(ENGINE_PARAMS);loadPromotions();try{validateSettings(preferences)}catch(e){preferences=OrderPolicy.defaults();state.date=preferences.startDate;toast('저장 설정 오류로 기본값을 사용합니다.')}FreshOrderEngine.configure({forecast:({item,storeId,asOf})=>{const values=currentPromotionForecast?.[item.ingredient_id];if(!values)throw Error('해당 기준일의 팀 수요 예측이 없습니다.');return values;}});loadDailyRecords();$('#dateSelect').value=state.date;$('#dateSelect').max='2099-12-31';$('#dateSelect').onchange=e=>{const value=e.target.value;if(!value||value<DailyLedger.SEED||value>e.target.max){e.target.value=state.date;toast('2026년 9월 30일부터 2099년 12월 31일까지 선택해주세요.');return}state.date=value;state.overrides={};render()};$('#initialDateBtn').onclick=()=>selectRecordDate(DailyLedger.SEED);$('#nextRecordBtn').onclick=()=>selectRecordDate(DailyLedger.nextDate(managerRecords,state.store));$('#storeTabs').onclick=e=>{const b=e.target.closest('[data-store]');if(b){state.store=b.dataset.store;state.overrides={};render()}};$('#chartSelect').onchange=e=>{state.selected=e.target.value;renderChart()};$('#search').oninput=e=>{state.search=e.target.value;renderTable()};$$('[data-nav]').forEach(b=>b.onclick=()=>{state.nav=b.dataset.nav;state.filter='all';renderTable();applyNav()});$('#reviewBtn').onclick=reviewOrders;$('#resetAllQty').onclick=()=>{state.overrides={};render();toast('모든 수량을 선택한 발주안의 추천값으로 초기화했습니다.')};$('#methodBtn').onclick=$('#assumptionsBtn').onclick=()=>$('#methodDialog').showModal();$('#closeMethod').onclick=()=>$('#methodDialog').close();$('#drawerOverlay').onclick=closeDrawer;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#drawer').hidden)closeDrawer();if(e.key==='Tab'&&!$('#drawer').hidden){const focusable=[...$('#drawer').querySelectorAll('button,input,select,a[href]')].filter(el=>!el.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});render();globalThis.DashboardTutorial?.ready()}catch(e){$('#inventoryBody').innerHTML='<tr><td colspan="7">데이터를 불러오지 못했습니다. 페이지를 새로고침해주세요.</td></tr>';console.error(e)}}init();
